# ---------------- Вывод ----------------
cols = ["ID пункта kb", "статус", "URL-доказательство", "влияние 1–3", "трудозатраты 1–3", "что исправить"]
with open(os.path.join(OUT, "findings.csv"), "w", encoding="utf-8-sig", newline="") as f:
    w = csv.writer(f, delimiter=";", quoting=csv.QUOTE_MINIMAL)
    w.writerow(cols)
    for i, st, urls, imp, eff, txt in R:
        w.writerow([i, st, " ".join(urls), imp, eff, txt])

ids = [r[0] for r in R]
dup = [k for k, v in Counter(ids).items() if v > 1]
assert not dup, dup
c = Counter(r[1] for r in R)
summary = {
    "total": len(R),
    "applicable_checked": c["выполнен"] + c["нарушен"],
    "violated": c["нарушен"],
    "ok": c["выполнен"],
    "na": c["не применим"],
    "nc": c["не проверить"],
    "atomic": sum(1 for i in ids if i in PTS or i in EXTRA),
    "playbook": sum(1 for i in ids if i in PB and i not in PTS),
}
json.dump(summary, open(os.path.join(OUT, "summary.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print(summary)
for i, st, urls, imp, eff, txt in sorted([r for r in R if r[1] == "нарушен"], key=lambda r: (-r[3] / r[4], -r[3])):
    print("%-15s %s/%s  %s" % (i, imp, eff, txt[txt.find("Факт:") + 6: txt.find("Факт:") + 90]))
